	@Test
	void rollbackReopenAndClearKeepSummaryLifetimeWithDictionaryLifetime() throws Exception {
		File values = new File(directory, "lifetime");
		ValueStore store = new ValueStore(values, config());
		long kept;
		try {
			kept = storeLiteral(store, "Committed Alpha Needle");
			assertTrue(store.mayMatchLiteralText(kept, query(Operation.CONTAINS, "alpha")));
			assertFalse(store.mayMatchLiteralText(kept, query(Operation.EQUALS, "definitely absent")));
			store.startTransaction(true);
			long rolledBack = store.storeValue(SimpleValueFactory.getInstance().createLiteral("Rolled Back Payload"));
			assertFalse(store.mayMatchLiteralText(rolledBack, query(Operation.STARTS_WITH, "absent")));
			store.rollback();
			assertTrue(store.mayMatchLiteralText(rolledBack, query(Operation.STARTS_WITH, "absent")),
					"an aborted dictionary ID must not retain a pruning proof");
		} finally {
			store.close();
		}
		store = new ValueStore(values, config());
		try {
			assertFalse(store.mayMatchLiteralText(kept, query(Operation.EQUALS, "definitely absent")));
			store.clear();
			assertTrue(store.mayMatchLiteralText(kept, query(Operation.STARTS_WITH, "absent")));
			long replacement = storeLiteral(store, "Replacement After Clear");
			assertTrue(store.mayMatchLiteralText(replacement, query(Operation.STARTS_WITH, "replacement")));
			assertFalse(store.mayMatchLiteralText(replacement, query(Operation.STARTS_WITH, "committed")));
		} finally {
			store.close();
		}
	}

