			long second = storeLiteral(store, "Second Existing Literal");
			store.writeTransaction((stack, txn) -> {
				int database = openDatabaseWithTxn(txn, "literal_text", 0);
				MDBVal key = MDBVal.calloc(stack).mv_data(stack.bytes(ValueStoreRecordCodec.idKey(first)));
				E(mdb_del(txn, database, key, null));
				key.mv_data(stack.bytes(ValueStoreRecordCodec.idKey(second)));
				E(mdb_put(txn, database, key, MDBVal.calloc(stack).mv_data(stack.bytes((byte) 1)), 0));
				return null;
			});
			var absent = query(Operation.EQUALS, "clearly not either stored literal");
			assertTrue(store.mayMatchLiteralText(first, absent));
			assertTrue(store.mayMatchLiteralText(second, absent));
