	@Test
	void retirementRetainsSummaryUntilPhysicalReclamationAndReuseReplacesIt() throws Exception {
		ValueStore store = new ValueStore(new File(directory, "reuse"), config());
		try {
			long retired = storeLiteral(store, "Retired Alpha Literal");
			store.startTransaction(true);
			store.gcIds(Set.of(retired), new HashSet<>());
			store.commit();
			assertFalse(store.mayMatchLiteralText(retired, query(Operation.STARTS_WITH, "replacement")),
					"reverse-only retirement keeps ID payloads and their summaries for older readers");
			store.writeTransaction((stack, txn) -> {
				store.freeUnusedIdsAndValues(stack, txn, null);
				return null;
			});
			assertTrue(store.mayMatchLiteralText(retired, query(Operation.STARTS_WITH, "replacement")));
			long replacement = storeLiteral(store, "Replacement Beta Literal");
			assertEquals(retired, replacement, "the test must exercise actual stored-ID reuse");
			assertTrue(store.mayMatchLiteralText(replacement, query(Operation.STARTS_WITH, "replacement")));
			assertFalse(store.mayMatchLiteralText(replacement, query(Operation.STARTS_WITH, "retired")));
		} finally {
			store.close();
		}
	}

	@ParameterizedTest
	@ValueSource(booleans = { false, true })
	void interruptedBackfillCommitsCoverageAndCursorTogetherAndResumesAfterReopen(boolean normalizerChange)
			throws Exception {
		File values = new File(directory, "resume");
		AtomicLong firstBatch = new AtomicLong();
		ValueStore store = new ValueStore(values, config().setValueDBSize(64L << 10)) {
			@Override
			void observeLiteralTextRebuildForTest(long written) {
				firstBatch.set(written);
				Thread.currentThread().interrupt();
			}
		};
		int count = 2300;
		long[] ids = new long[count];
		try {
			Value[] literals = new Value[count];
			for (int i = 0; i < count; i++) {
				literals[i] = SimpleValueFactory.getInstance().createLiteral("PRIOR LITERAL " + i);
			}
			store.startTransaction(true);
			store.storeValues(literals, ids, count);
			store.commit();
			if (normalizerChange) {
				Locale.setDefault(Locale.forLanguageTag("tr-TR"));
			} else {
				deleteSummaries(store, ids);
			}
			assertThrows(InterruptedIOException.class, store::rebuildLiteralTextIndex);
			assertTrue(Thread.interrupted());
			assertTrue(firstBatch.get() > 0 && firstBatch.get() < count);
			assertTrue(store.mayMatchLiteralText(ids[count - 1], query(Operation.EQUALS, "absent")),
					"a partial backfill must retain UNKNOWN coverage for unvisited literals");
		} finally {
			Thread.interrupted();
			store.close();
		}
		store = new ValueStore(values, config().setValueDBSize(64L << 10));
		try {
			assertEquals(count - firstBatch.get(), store.rebuildLiteralTextIndex());
			for (int i = 0; i < ids.length; i++) {
				assertFalse(store.mayMatchLiteralText(ids[i], query(Operation.EQUALS, "absent from every literal")));
				assertTrue(store.mayMatchLiteralText(ids[i], query(Operation.EQUALS,
						(normalizerChange ? "prıor lıteral " : "prior literal ") + i)));
			}
		} finally {
			store.close();
		}
	}

	@Test
	void freshPreparedAndDeferredRawBulkWritersBothPersistSummaries() throws Exception {
		ValueStore preparedStore = new ValueStore(new File(directory, "prepared"), config().setValueDBSize(64L << 10));
		try {
			Value[] values = { SimpleValueFactory.getInstance().createLiteral("Prepared Needle One"),
					SimpleValueFactory.getInstance().createLiteral("Prepared Needle Two " + "long ".repeat(2000)) };
			preparedStore.startTransaction(true);
			ValueStore.FreshValueSession session = preparedStore.startFreshValueSessionIfEmpty();
			assertNotNull(session);
			preparedStore.reservePreparedValueClosureCapacity(session, values);
			ValueStore.PreparedValueBatch prepared = preparedStore.prepareFreshValues(session, values);
			preparedStore.persistPreparedValues(prepared);
			preparedStore.commit();
			preparedStore.commitFreshValueTransaction(session);
			preparedStore.publishPreparedValues(prepared);
			for (long id : prepared.ids()) {
				assertTrue(preparedStore.mayMatchLiteralText(id, query(Operation.STARTS_WITH, "prepared needle")));
				assertFalse(preparedStore.mayMatchLiteralText(id, query(Operation.STARTS_WITH, "unrelated")));
			}
		} finally {
			preparedStore.close();
		}
		File rawDirectory = new File(directory, "raw");
		LmdbStoreConfig config = config().setValueDBSize(64L << 10);
		ValueStore raw = new ValueStore(rawDirectory, StoreProperties.forDictionary(rawDirectory), config, true);
		try {
			long id = ValueIds.createId(ValueIds.T_LITERAL, 100L);
			byte[] key = ValueStoreRecordCodec.idKey(id);
			byte[] record = ValueStoreRecordCodec.literalData(
					SimpleValueFactory.getInstance().createLiteral("Raw Bulk Needle"), 0L, false);
			List<ValueStore.BulkRecord> records = new ArrayList<>();
			records.add(new ValueStore.BulkRecord(key, record));
			if (record.length <= ValueStoreRecordCodec.MAX_INLINE_KEY_BYTES) {
				records.add(new ValueStore.BulkRecord(record, key));
			} else {
				records.add(new ValueStore.BulkRecord(ValueStoreRecordCodec.hashKey(ValueStoreRecordCodec.hash(record)),
						key));
			}
			records.sort((left, right) -> Arrays.compareUnsigned(left.key(), right.key()));
			AtomicInteger position = new AtomicInteger();
			raw.appendBulkRecords(() -> {
				int index = position.getAndIncrement();
				return index < records.size() ? records.get(index) : null;
			}, 1, 4096L);
			raw.completeBulkInitialization(config);
			assertTrue(raw.mayMatchLiteralText(id, query(Operation.CONTAINS, "bulk needle")));
			assertFalse(raw.mayMatchLiteralText(id, query(Operation.STARTS_WITH, "unrelated")));
		} finally {
			raw.close();
		}
	}

	@Test
	void rejectedDuplicateBulkPayloadCannotReplaceThePersistedLiteralSummary() throws Exception {
		ValueStore store = new ValueStore(new File(directory, "duplicate-bulk"), config());
		try {
			long id = storeLiteral(store, "Original Accepted Literal");
			byte[] original = store.getData(id);
			byte[] rejected = ValueStoreRecordCodec.literalData(
					SimpleValueFactory.getInstance().createLiteral("Contradictory Rejected Payload"), 0L, false);
			ValueStore.BulkRecord duplicate = new ValueStore.BulkRecord(ValueStoreRecordCodec.idKey(id), rejected);
			AtomicInteger position = new AtomicInteger();
			store.appendBulkRecords(() -> position.getAndIncrement() == 0 ? duplicate : null, 1, 4096L);
			assertArrayEquals(original, store.getData(id), "MDB_NOOVERWRITE retains the authoritative payload");
			assertTrue(store.mayMatchLiteralText(id, query(Operation.EQUALS, "original accepted literal")),
					"a failed native insert must retain the summary of the actual dictionary bytes");
			assertFalse(store.mayMatchLiteralText(id, query(Operation.STARTS_WITH, "contradictory")));
		} finally {
			store.close();
		}
	}

	@Test
	@Timeout(20)
	void metadataOnlyOwnedCommitsReserveAuthorityPagesWithAPinnedReader() throws Exception {
		ValueStore store = new ValueStore(new File(directory, "metadata-capacity"), config().setValueDBSize(64L << 10));
		try {
			long id = storeLiteral(store, "Unchanged Across Metadata Commits");
			long before = store.mapSizeBytes();
			try (ValueStore.ReadSnapshotReservation reservation = store.reserveReadSnapshot();
					ValueStore.ReadSnapshot snapshot = reservation.start()) {
				assertTrue(store.mayMatchLiteralText(snapshot, id, query(Operation.STARTS_WITH, "unchanged")));
				for (int i = 0; i < 256; i++) {
					store.startTransaction(true);
					store.commit();
				}
			}
			assertTrue(store.mapSizeBytes() > before, "the pinned reader must force actual metadata page growth");
			assertTrue(store.mayMatchLiteralText(id, query(Operation.STARTS_WITH, "unchanged")));
			assertFalse(store.mayMatchLiteralText(id, query(Operation.STARTS_WITH, "absent")));
		} finally {
			store.close();
		}
	}

	private long storeLiteral(ValueStore store, String label) throws IOException {
		store.startTransaction(true);
		long id = store.storeValue(SimpleValueFactory.getInstance().createLiteral(label));
		store.commit();
		return id;
	}

	private LiteralTextSummary.Query query(Operation operation, String evaluatedNeedle) {
		return LiteralTextSummary.prepare(operation, evaluatedNeedle, Locale.getDefault());
	}

	private void deleteSummaries(ValueStore store, long[] ids) throws IOException {
		store.writeTransaction((stack, txn) -> {
			int database = openDatabaseWithTxn(txn, "literal_text", 0);
			MDBVal key = MDBVal.calloc(stack);
			for (long id : ids) {
				stack.push();
				try {
					key.mv_data(stack.bytes(ValueStoreRecordCodec.idKey(id)));
					E(mdb_del(txn, database, key, null));
				} finally {
					stack.pop();
				}
			}
			return null;
		});
	}

	private <T> T inspectClosedStore(File values, LmdbUtil.Transaction<T> inspection) throws IOException {
		return accessClosedStore(values, inspection, false);
	}

	private <T> T accessClosedStore(File values, LmdbUtil.Transaction<T> operation, boolean write) throws IOException {
		long environment;
		try (MemoryStack stack = stackPush()) {
			PointerBuffer handle = stack.mallocPointer(1);
			E(mdb_env_create(handle));
			environment = handle.get(0);
		}
		try {
			E(mdb_env_set_maxdbs(environment, 32));
			E(mdb_env_open(environment, values.getAbsolutePath(), MDB_NOTLS, 0664));
			return write ? LmdbUtil.writeTransaction(environment, operation)
					: LmdbUtil.readTransaction(environment, operation);
		} finally {
			mdb_env_close(environment);
		}
	}
